import React, { useEffect, useState } from 'react';
import {
  LineChart, Line, BarChart, Bar, XAxis, YAxis, CartesianGrid, 
  Tooltip, Legend, ResponsiveContainer, PieChart, Pie, Cell
} from 'recharts';
import { FiUsers, FiTrendingUp, FiUserCheck, FiUserX } from 'react-icons/fi';
import '../admin.css';

const UserAnalytics = ({ rows = [] }) => {
  const [tabValue, setTabValue] = useState(0);
  const [rangeOption, setRangeOption] = useState('month');
  const [analyticsData, setAnalyticsData] = useState({
    totalUsers: 2450,
    activeUsers: 1823,
    newUsersToday: 45,
    newUsersThisMonth: 890,
    conversionRate: 23.5,
    churnRate: 2.1,
    avgSessionDuration: 8.5,
    userGrowth: [
      { date: 'Mar 1', users: 1800, active: 1200 },
      { date: 'Mar 8', users: 1950, active: 1350 },
      { date: 'Mar 15', users: 2100, active: 1550 },
      { date: 'Mar 22', users: 2300, active: 1750 },
      { date: 'Mar 29', users: 2450, active: 1823 }
    ],
    usersByRole: [
      { name: 'Job Seekers', value: 1520, fill: '#00d4ff' },
      { name: 'Employers', value: 650, fill: '#00d973' },
      { name: 'Admins', value: 280, fill: '#ffd700' }
    ],
    usersByTier: [
      { name: 'Free', value: 1850, percentage: 75.5 },
      { name: 'Premium', value: 450, percentage: 18.4 },
      { name: 'Pro', value: 150, percentage: 6.1 }
    ],
    topCountries: [
      { country: 'Kenya', users: 650, percentage: 26.5 },
      { country: 'Nigeria', users: 485, percentage: 19.8 },
      { country: 'Uganda', users: 380, percentage: 15.5 },
      { country: 'Tanzania', users: 295, percentage: 12.0 },
      { country: 'Other', users: 640, percentage: 26.1 }
    ],
    userEngagement: [
      { metric: 'Daily Active', count: 1823, trend: 8.5 },
      { metric: 'Weekly Active', count: 2100, trend: 5.2 },
      { metric: 'Monthly Active', count: 2300, trend: 3.1 },
      { metric: 'One-time Users', count: 150, trend: -12.3 }
    ],
    kpiActive: 0,
    kpiSignedOut: 0,
    totalActiveNow: 0,
    totalSignedOut: 0,
    rangeLabel: 'Last 30 days'
  });
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchAnalytics = async () => {
      try {
        // Process rows data if provided
        if (rows && rows.length > 0) {
          const now = new Date();
          let from;
          if (rangeOption === 'daily') {
            from = new Date(now.getTime() - 24 * 60 * 60 * 1000);
          } else if (rangeOption === 'week') {
            from = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
          } else if (rangeOption === 'year') {
            from = new Date(now.getFullYear() - 1, now.getMonth(), now.getDate());
          } else {
            from = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
          }

          const totalUsersLocal = rows.length;
          let totalActiveNowLocal = 0;
          let totalSignedOutLocal = 0;
          let activePeriod = 0;
          let signedOutPeriod = 0;

          const ONLINE_WINDOW_MINUTES = 5;
          const onlineWindowMs = ONLINE_WINDOW_MINUTES * 60 * 1000;

          rows.forEach((u) => {
            const createdAt = u.created_at ? new Date(u.created_at) : null;
            const lastActiveAt = u.last_active_at ? new Date(u.last_active_at) : createdAt;
            const deactivatedAt = u.deactivated_at ? new Date(u.deactivated_at) : null;

            const isOnlineNow = !!(lastActiveAt && now.getTime() - lastActiveAt.getTime() <= onlineWindowMs);
            const isSignedOutByTimestamp = !!deactivatedAt && deactivatedAt <= now;
            const isSignedIn = !isSignedOutByTimestamp;

            if (isOnlineNow) totalActiveNowLocal += 1;
            if (isSignedOutByTimestamp) totalSignedOutLocal += 1;

            if (isSignedIn) {
              const activityTime = lastActiveAt || createdAt;
              if (activityTime && activityTime >= from && activityTime <= now) {
                activePeriod += 1;
              }
            } else if (isSignedOutByTimestamp && deactivatedAt && deactivatedAt >= from && deactivatedAt <= now) {
              signedOutPeriod += 1;
            }
          });

          const rangeLabelLocal = rangeOption === 'daily' ? 'Last 24 hours' : rangeOption === 'week' ? 'Last 7 days' : rangeOption === 'year' ? 'Last 12 months' : 'Last 30 days';

          setAnalyticsData(prev => ({
            ...prev,
            kpiActive: activePeriod,
            kpiSignedOut: signedOutPeriod,
            totalActiveNow: totalActiveNowLocal,
            totalUsers: totalUsersLocal,
            totalSignedOut: totalSignedOutLocal,
            rangeLabel: rangeLabelLocal,
            activeUsers: totalActiveNowLocal
          }));
        }
      } catch (error) {
        console.error('Failed to fetch analytics:', error);
      } finally {
        setLoading(false);
      }
    };

    fetchAnalytics();
  }, [rows, rangeOption]);

  const StatCard = ({ icon: Icon, label, value, trend = null, suffix = '' }) => (
    <div style={{ padding: '16px', background: 'linear-gradient(135deg, rgba(0, 212, 255, 0.12) 0%, rgba(0, 212, 255, 0.04) 100%)', border: '1px solid rgba(0, 212, 255, 0.2)', borderRadius: '10px' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: '8px' }}>
        <div>
          <div style={{ fontSize: '12px', color: '#8696a0', marginBottom: '6px' }}>{label}</div>
          <div style={{ fontSize: '28px', fontWeight: '700', color: '#ffffff' }}>
            {typeof value === 'number' ? value.toLocaleString() : value}{suffix}
          </div>
        </div>
        <Icon style={{ fontSize: 24, opacity: 0.6, color: '#00d4ff' }} />
      </div>
      {trend !== null && trend !== undefined && (
        <div style={{ fontSize: '11px', color: trend > 0 ? '#00d973' : '#ff6b6b' }}>
          {trend > 0 ? '↑' : '↓'} {Math.abs(trend)}% this month
        </div>
      )}
    </div>
  );

  if (loading) {
    return <div style={{ padding: '20px', color: '#8696a0' }}>Loading analytics...</div>;
  }

  return (
    <div style={{ padding: '24px' }}>
      {/* Header */}
      <div style={{ marginBottom: '28px' }}>
        <h1 style={{ fontSize: '28px', fontWeight: '700', color: '#ffffff', margin: 0, letterSpacing: '-0.5px' }}>User Analytics</h1>
        <p style={{ fontSize: '13px', color: '#8696a0', margin: '6px 0 0 0' }}>User behavior, demographics, and engagement metrics</p>
      </div>

      {/* Range Selector (for basic view) */}
      {tabValue === 0 && (
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: '16px', marginBottom: '20px', flexWrap: 'wrap' }}>
          <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap' }}>
            {['daily', 'week', 'month', 'year'].map((key) => (
              <button
                key={key}
                className="btn"
                style={{
                  padding: '6px 14px',
                  borderRadius: '999px',
                  background: rangeOption === key ? '#005c4b' : '#202c33',
                  color: '#e9edef',
                  border: 'none',
                  fontSize: '12px',
                  textTransform: 'capitalize',
                  cursor: 'pointer',
                  transition: 'all 0.2s ease'
                }}
                onClick={() => setRangeOption(key)}
              >
                {key}
              </button>
            ))}
          </div>
          <div style={{ color: '#8696a0', fontSize: '12px' }}>{analyticsData.rangeLabel}</div>
        </div>
      )}

      {/* Key Statistics */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '16px', marginBottom: '28px' }}>
        <StatCard 
          icon={FiUsers} 
          label="Total Users" 
          value={analyticsData.totalUsers.toLocaleString()} 
          trend={12.5}
        />
        <StatCard 
          icon={FiUserCheck} 
          label="Active Users" 
          value={analyticsData.activeUsers.toLocaleString()} 
          trend={8.3}
        />
        <StatCard 
          icon={FiTrendingUp} 
          label="New This Month" 
          value={analyticsData.newUsersThisMonth} 
          trend={5.2}
        />
        <StatCard 
          icon={FiUserX} 
          label="Conversion Rate" 
          value={analyticsData.conversionRate} 
          suffix="%" 
          trend={2.8}
        />
      </div>

      {/* Tab Navigation */}
      <div style={{ display: 'flex', gap: '8px', marginBottom: '20px', borderBottom: '1px solid rgba(134, 150, 160, 0.1)', paddingBottom: '12px' }}>
        {[
          { label: 'Overview', id: 0 },
          { label: 'Growth Trends', id: 1 },
          { label: 'Demographics', id: 2 },
          { label: 'Engagement', id: 3 },
          { label: 'Tiers', id: 4 }
        ].map((tab) => (
          <button
            key={tab.id}
            onClick={() => setTabValue(tab.id)}
            style={{
              padding: '8px 16px',
              background: tabValue === tab.id ? 'rgba(0, 212, 255, 0.15)' : 'transparent',
              border: `2px solid ${tabValue === tab.id ? '#00d4ff' : 'transparent'}`,
              color: tabValue === tab.id ? '#00d4ff' : '#8696a0',
              borderRadius: '6px',
              fontSize: '13px',
              fontWeight: tabValue === tab.id ? '600' : '500',
              cursor: 'pointer',
              transition: 'all 0.2s ease'
            }}
          >
            {tab.label}
          </button>
        ))}
      </div>

      {/* Tab Content */}
      <div style={{ padding: '16px', background: 'rgba(13, 27, 42, 1)', border: '1px solid rgba(134, 150, 160, 0.1)', borderRadius: '12px' }}>
        {/* Overview Tab */}
        {tabValue === 0 && (
          <div>
            <h3 style={{ marginBottom: '16px', color: '#d0d8e0', fontSize: '14px', fontWeight: '600', margin: 0 }}>Overview Summary</h3>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '12px' }}>
              <div style={{ background: '#111b21', borderRadius: '8px', padding: '12px', border: '1px solid #202c33' }}>
                <div style={{ fontSize: '11px', color: '#8696a0', marginBottom: '4px' }}>Active ({analyticsData.rangeLabel})</div>
                <div style={{ fontSize: '22px', fontWeight: '600', color: '#e9edef' }}>{analyticsData.kpiActive}</div>
              </div>
              <div style={{ background: '#111b21', borderRadius: '8px', padding: '12px', border: '1px solid #202c33' }}>
                <div style={{ fontSize: '11px', color: '#8696a0', marginBottom: '4px' }}>Signed-out ({analyticsData.rangeLabel})</div>
                <div style={{ fontSize: '22px', fontWeight: '600', color: '#e9edef' }}>{analyticsData.kpiSignedOut}</div>
              </div>
              <div style={{ background: '#111b21', borderRadius: '8px', padding: '12px', border: '1px solid #202c33' }}>
                <div style={{ fontSize: '11px', color: '#8696a0', marginBottom: '4px' }}>Active Now</div>
                <div style={{ fontSize: '22px', fontWeight: '600', color: '#e9edef' }}>{analyticsData.totalActiveNow}</div>
                <div style={{ fontSize: '10px', color: '#8696a0', marginTop: '4px' }}>of {analyticsData.totalUsers.toLocaleString()} users</div>
              </div>
              <div style={{ background: '#111b21', borderRadius: '8px', padding: '12px', border: '1px solid #202c33' }}>
                <div style={{ fontSize: '11px', color: '#8696a0', marginBottom: '4px' }}>Total Signed-out</div>
                <div style={{ fontSize: '22px', fontWeight: '600', color: '#e9edef' }}>{analyticsData.totalSignedOut}</div>
              </div>
            </div>
          </div>
        )}

        {/* Growth Trends */}
        {tabValue === 1 && (
          <div>
            <h3 style={{ marginBottom: '16px', color: '#ffffff', fontSize: '14px', fontWeight: '600', margin: 0 }}>User Growth Over Time</h3>
            <ResponsiveContainer width="100%" height={300}>
              <LineChart data={analyticsData.userGrowth} margin={{ top: 10, right: 30, left: 0, bottom: 0 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="rgba(0, 212, 255, 0.1)" vertical={false} />
                <XAxis dataKey="date" stroke="rgba(134, 150, 160, 0.3)" style={{ fontSize: '12px' }} />
                <YAxis stroke="rgba(134, 150, 160, 0.3)" style={{ fontSize: '12px' }} />
                <Tooltip contentStyle={{ backgroundColor: 'rgba(11, 20, 26, 0.95)', border: '1px solid rgba(0, 212, 255, 0.3)', borderRadius: '8px' }} />
                <Legend />
                <Line 
                  type="monotone" 
                  dataKey="users" 
                  stroke="#00d4ff" 
                  strokeWidth={2.5}
                  dot={{ fill: '#00d4ff', r: 4 }}
                  name="Total Users"
                />
                <Line 
                  type="monotone" 
                  dataKey="active" 
                  stroke="#00d973" 
                  strokeWidth={2.5}
                  dot={{ fill: '#00d973', r: 4 }}
                  name="Active Users"
                />
              </LineChart>
            </ResponsiveContainer>
          </div>
        )}

        {/* Demographics */}
        {tabValue === 2 && (
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(350px, 1fr))', gap: '24px' }}>
            {/* Countries Table */}
            <div>
              <h4 style={{ marginBottom: '12px', color: '#ffffff', fontSize: '13px', fontWeight: '600', margin: 0 }}>Users by Country</h4>
              <div style={{ overflowX: 'auto' }}>
                <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '13px' }}>
                  <thead>
                    <tr style={{ borderBottom: '1px solid rgba(134, 150, 160, 0.15)' }}>
                      <th style={{ padding: '8px', textAlign: 'left', color: '#8696a0', fontWeight: '500' }}>Country</th>
                      <th style={{ padding: '8px', textAlign: 'right', color: '#8696a0', fontWeight: '500' }}>Users</th>
                      <th style={{ padding: '8px', textAlign: 'right', color: '#8696a0', fontWeight: '500' }}>%</th>
                    </tr>
                  </thead>
                  <tbody>
                    {analyticsData.topCountries.map((country, idx) => (
                      <tr key={idx} style={{ borderBottom: '1px solid rgba(134, 150, 160, 0.08)' }}>
                        <td style={{ padding: '8px', color: '#d0d8e0' }}>{country.country}</td>
                        <td style={{ padding: '8px', textAlign: 'right', color: '#d0d8e0' }}>{country.users.toLocaleString()}</td>
                        <td style={{ padding: '8px', textAlign: 'right', color: '#8696a0' }}>{country.percentage}%</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>

            {/* Roles Pie Chart */}
            <div>
              <h4 style={{ marginBottom: '12px', color: '#ffffff', fontSize: '13px', fontWeight: '600', margin: 0 }}>Users by Role</h4>
              <ResponsiveContainer width="100%" height={250}>
                <PieChart>
                  <Pie
                    data={analyticsData.usersByRole}
                    cx="50%"
                    cy="50%"
                    labelLine={false}
                    label={({ name, value }) => `${name}: ${value}`}
                    outerRadius={80}
                    fill="#8884d8"
                    dataKey="value"
                  >
                    {analyticsData.usersByRole.map((entry, index) => (
                      <Cell key={`cell-${index}`} fill={entry.fill} />
                    ))}
                  </Pie>
                  <Tooltip contentStyle={{ backgroundColor: 'rgba(11, 20, 26, 0.95)', border: '1px solid rgba(0, 212, 255, 0.3)' }} />
                </PieChart>
              </ResponsiveContainer>
            </div>
          </div>
        )}

        {/* Engagement */}
        {tabValue === 3 && (
          <div>
            <h3 style={{ marginBottom: '16px', color: '#ffffff', fontSize: '14px', fontWeight: '600', margin: 0 }}>User Engagement Metrics</h3>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '12px' }}>
              {analyticsData.userEngagement.map((item, idx) => (
                <div key={idx} style={{ background: '#111b21', borderRadius: '8px', padding: '12px', border: '1px solid #202c33' }}>
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '8px' }}>
                    <div style={{ fontSize: '13px', fontWeight: '600', color: '#d0d8e0' }}>{item.metric}</div>
                    <div style={{ fontSize: '11px', color: item.trend > 0 ? '#00d973' : '#ff6b6b' }}>
                      {item.trend > 0 ? '+' : ''}{item.trend}%
                    </div>
                  </div>
                  <div style={{ fontSize: '20px', fontWeight: '600', color: '#00d4ff', marginBottom: '8px' }}>
                    {item.count.toLocaleString()}
                  </div>
                  <div style={{ background: 'rgba(0, 212, 255, 0.1)', height: '4px', borderRadius: '2px' }}>
                    <div style={{ background: '#00d4ff', height: '100%', width: `${Math.min((item.count / 2500) * 100, 100)}%`, borderRadius: '2px' }} />
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Tiers */}
        {tabValue === 4 && (
          <div>
            <h3 style={{ marginBottom: '16px', color: '#ffffff', fontSize: '14px', fontWeight: '600', margin: 0 }}>Users by Subscription Tier</h3>
            <div style={{ overflowX: 'auto' }}>
              <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '13px' }}>
                <thead>
                  <tr style={{ borderBottom: '1px solid rgba(134, 150, 160, 0.15)' }}>
                    <th style={{ padding: '12px', textAlign: 'left', color: '#8696a0', fontWeight: '500' }}>Tier</th>
                    <th style={{ padding: '12px', textAlign: 'right', color: '#8696a0', fontWeight: '500' }}>Users</th>
                    <th style={{ padding: '12px', textAlign: 'right', color: '#8696a0', fontWeight: '500' }}>%</th>
                  </tr>
                </thead>
                <tbody>
                  {analyticsData.usersByTier.map((tier, idx) => (
                    <tr key={idx} style={{ borderBottom: '1px solid rgba(134, 150, 160, 0.08)' }}>
                      <td style={{ padding: '12px', color: '#d0d8e0', fontWeight: '500' }}>{tier.name}</td>
                      <td style={{ padding: '12px', textAlign: 'right', color: '#d0d8e0' }}>{tier.value.toLocaleString()}</td>
                      <td style={{ padding: '12px', textAlign: 'right' }}>
                        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'flex-end', gap: '8px' }}>
                          <div style={{ background: 'rgba(0, 212, 255, 0.1)', height: '4px', width: `${tier.percentage}px`, borderRadius: '2px', background: '#00d973' }} />
                          <span style={{ color: '#8696a0', minWidth: '35px' }}>{tier.percentage}%</span>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default UserAnalytics;
